function renderAssets(){const category=$('#asset-category').value||assetCategory,query=$('#search').value.toLowerCase();const structural=[['wall','Wall',[3,3.2,.2]],['floor','Floor slab',[4,.16,4]],['roof','Ceiling / roof',[4,.16,4]],['doorway','Door opening',[3.2,3.2,.2]],['window','Window wall',[3,3.2,.2]],['stairs','Stair assembly',[1.8,3.2,5.6]],['light','Point light',[.15,.15,.15]]].map(([id,name,size])=>({id,name,size,structural:true}));const rows=category==='Structure'?structural:ASSETS.filter(a=>category==='All'||a.category===category);$('#asset-cards').innerHTML=rows.filter(a=>a.name.toLowerCase().includes(query)).map(a=>{const thumb=a.structural?null:(a.thumbnail||(!['Nature','Vehicles','Infrastructure'].includes(a.category)?'editor/thumbnails/'+a.id+'.webp':'editor2/thumbnails/'+a.id+'.webp'));return`<button class="asset-card" data-asset="${a.id}" draggable="true">${thumb?`<img src="${thumb}" alt="${esc(a.name)}">`:`<div class="asset-symbol">${a.structural?icon[a.id]:a.category==='Nature'?'♧':a.category==='Vehicles'?'▰':'⌁'}</div>`}<span>${esc(a.name)}</span><small>${a.structural?'Shared structure':'3D model'}</small></button>`}).join('');for(const b of $('#asset-cards').children){b.onclick=()=>addAsset(rows.find(a=>a.id===b.dataset.asset));b.ondragstart=e=>e.dataTransfer.setData('application/field-signal-asset',JSON.stringify(rows.find(a=>a.id===b.dataset.asset)));}}
